def topo_sort_dfs(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
    visited = [0] * n   # 0=unvisited, 1=in-stack, 2=done
    result = []
    has_cycle = [False]

    def dfs(node):
        if visited[node] == 1:
            has_cycle[0] = True; return
        if visited[node] == 2:
            return
        visited[node] = 1
        for nei in graph[node]:
            dfs(nei)
        visited[node] = 2
        result.append(node)

    for i in range(n):
        if visited[i] == 0:
            dfs(i)
    return [] if has_cycle[0] else result[::-1]
