def findMinHeightTrees(n, edges):
    if n == 1: return [0]
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v); adj[v].add(u)
    leaves = deque(i for i in range(n) if len(adj[i]) == 1)
    remaining = n
    while remaining > 2:
        remaining -= len(leaves)
        new_leaves = deque()
        while leaves:
            leaf = leaves.popleft()
            nei = adj[leaf].pop()
            adj[nei].remove(leaf)
            if len(adj[nei]) == 1:
                new_leaves.append(nei)
        leaves = new_leaves
    return list(leaves)

